pub mod bridge;pub mod db;pub mod git;pub mod parser;pub mod pty;pub mod shell;pub mod watcher;pub mod ws;use std::collections::VecDeque;use std::path::{Path, PathBuf};use std::sync::atomic::{AtomicBool, Ordering};use std::sync::mpsc::RecvTimeoutError;use std::sync::{Arc, Mutex};use std::thread;use std::time::{Duration, Instant};use tauri::{Emitter, Manager, State};/// App-managed shared state: the SQLite connection, the watched project/// root, the single active interactive PTY session, the trace parser,/// the extension WebSocket, and the approval queue.pub(crate) struct AppState {    pub(crate) conn: Mutex<rusqlite::Connection>,    pub(crate) project_root: Mutex<Option<PathBuf>>,    pub(crate) session: Mutex<Option<pty::SessionPty>>,    pub(crate) parser: Mutex<parser::Parser>,    pub(crate) pair_code: Mutex<String>,    pub(crate) ws_connected: AtomicBool,    pub(crate) ws_tx: Mutex<Option<Arc<Mutex<tungstenite::WebSocket<std::net::TcpStream>>>>>,    pub(crate) bridge: Mutex<bridge::Bridge>,    pub(crate) session_id: Mutex<Option<i64>>,    pub(crate) objective: Mutex<Option<String>>,    /// Recent "editing X" steps, for watcher cross-correlation.    pub(crate) recent_edits: Mutex<VecDeque<(String, Instant)>>,}/// The single active interactive session may only live inside the/// configured project root G현 groundwork for M2's path-containment model.fn path_inside(candidate: &Path, root: &Path) -> bool {    let cand = candidate        .canonicalize()        .unwrap_or_else(|_| candidate.to_path_buf());    let root = root.canonicalize().unwrap_or_else(|_| root.to_path_buf());    cand.starts_with(&root)}/// Event payloads streamed to the frontend over Tauri events.#[derive(Clone, serde::Serialize)]struct PtySpawned {    shell: String,    cwd: String,}#[derive(Clone, serde::Serialize)]struct PtyOutput {    data: String,}#[derive(Clone, serde::Serialize)]struct PtyExit {    code: Option<i32>,}#[derive(Clone, serde::Serialize)]struct PtyOverflow {    dropped: u64,}// --- commands ---------------------------------------------------------------/// Initialize / open the local database and return the connection.#[tauri::command]fn init_database(state: State<'_, AppState>, db_path: String) -> Result<Vec<String>, String> {    let conn = db::open_and_migrate(std::path::Path::new(&db_path)).map_err(|e| e.to_string())?;    let applied = db::applied_versions(&conn).map_err(|e| e.to_string())?;    *state.conn.lock().unwrap() = conn;    Ok(applied)}/// Set the project folder this app monitors (persisted).#[tauri::command]fn set_project_root(state: State<'_, AppState>, path: String) -> Result<(), String> {    let p = std::path::PathBuf::from(path);    if !p.is_dir() {        return Err(format!("not a directory: {}", p.display()));    }    *state.project_root.lock().unwrap() = Some(p.clone());    let _ = db::set_setting(        &state.conn.lock().unwrap(),        "project_root",        &p.display().to_string(),    );    Ok(())}/// Restore the persisted project root (frontend calls on startup).#[tauri::command]fn get_project_root(state: State<'_, AppState>) -> Result<Option<String>, String> {    Ok(state        .project_root        .lock()        .unwrap()        .clone()        .map(|p| p.display().to_string()))}/// Get the current git status of the project (working tree).#[tauri::command]fn git_status(state: State<'_, AppState>) -> Result<Vec<git::GitFileStatus>, String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let repo = git::open_repo(&root).map_err(|e| e.to_string())?;    git::status(&repo).map_err(|e| e.to_string())}/// Get the current branch of the project.#[tauri::command]fn git_branch(state: State<'_, AppState>) -> Result<Option<String>, String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let repo = git::open_repo(&root).map_err(|e| e.to_string())?;    Ok(git::current_branch(&repo))}/// Stage all changes and commit them with the given message.#[tauri::command]fn git_commit(state: State<'_, AppState>, message: String) -> Result<String, String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let repo = git::open_repo(&root).map_err(|e| e.to_string())?;    let oid = git::commit(&repo, &message).map_err(|e| e.to_string())?;    Ok(oid.to_string())}// --- M1.6 git panel backend -------------------------------------------------#[tauri::command]fn git_diff(state: State<'_, AppState>) -> Result<Vec<git::FileDiff>, String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let repo = git::open_repo(&root).map_err(|e| e.to_string())?;    git::diff_workdir(&repo).map_err(|e| e.to_string())}#[tauri::command]fn git_stage(state: State<'_, AppState>, path: String) -> Result<(), String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let repo = git::open_repo(&root).map_err(|e| e.to_string())?;    git::stage(&repo, &path).map_err(|e| e.to_string())}#[tauri::command]fn git_unstage(state: State<'_, AppState>, path: String) -> Result<(), String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let repo = git::open_repo(&root).map_err(|e| e.to_string())?;    git::unstage(&repo, &path).map_err(|e| e.to_string())}#[tauri::command]fn git_stage_all(state: State<'_, AppState>) -> Result<(), String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let repo = git::open_repo(&root).map_err(|e| e.to_string())?;    git::stage_all(&repo).map_err(|e| e.to_string())}#[tauri::command]fn git_branches(state: State<'_, AppState>) -> Result<Vec<git::BranchInfo>, String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let repo = git::open_repo(&root).map_err(|e| e.to_string())?;    git::branches(&repo).map_err(|e| e.to_string())}#[tauri::command]fn git_checkout(state: State<'_, AppState>, name: String) -> Result<(), String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let repo = git::open_repo(&root).map_err(|e| e.to_string())?;    git::checkout(&repo, &name).map_err(|e| e.to_string())}#[tauri::command]fn git_log(    state: State<'_, AppState>,    limit: Option<usize>,) -> Result<Vec<git::CommitInfo>, String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let repo = git::open_repo(&root).map_err(|e| e.to_string())?;    git::log(&repo, limit.unwrap_or(50)).map_err(|e| e.to_string())}#[tauri::command]fn git_commit_diff(state: State<'_, AppState>, oid: String) -> Result<String, String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let repo = git::open_repo(&root).map_err(|e| e.to_string())?;    git::commit_diff(&repo, &oid).map_err(|e| e.to_string())}// --- terminal ----------------------------------------------------------------/// Run a shell command in the project directory and return its output./// One-shot only G현 never routed through the interactive session.#[tauri::command]fn run_command(    state: State<'_, AppState>,    command: String,    timeout_ms: Option<u64>,    max_output_bytes: Option<usize>,) -> Result<pty::CommandOutput, String> {    let cwd = state        .project_root        .lock()        .unwrap()        .clone()        .unwrap_or_else(|| std::path::PathBuf::from("."));    let timeout = Duration::from_millis(timeout_ms.unwrap_or(60_000));    let max_output = max_output_bytes.unwrap_or(1_048_576);    pty::run_command(&command, &cwd, timeout, max_output).map_err(|e| e.to_string())}/// Spawn the single interactive PTY session (shell). Any prior session is/// killed and replaced G현 sessions never accumulate.#[tauri::command]fn pty_spawn(    state: State<'_, AppState>,    app: tauri::AppHandle,    cwd: String,    rows: u16,    cols: u16,) -> Result<PtySpawned, String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let cwd = validate_cwd(&cwd, &root)?;    let shell = shell::Shell::detect();    let session = pty::spawn_session(shell, &cwd, rows, cols).map_err(|e| e.to_string())?;    let name = shell.name().to_string();    install_session(&state, &app, session, &name);    let spawned = PtySpawned {        shell: name,        cwd: cwd.display().to_string(),    };    let _ = app.emit("pty://spawned", spawned.clone());    Ok(spawned)}/// Spawn the interactive session running Claude Code (M1.3).#[tauri::command]fn claude_spawn(    state: State<'_, AppState>,    app: tauri::AppHandle,    cwd: String,    rows: u16,    cols: u16,) -> Result<PtySpawned, String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let cwd = validate_cwd(&cwd, &root)?;    // Windows: `claude` is an npm shim (claude.cmd) G현 spawn via cmd /c.    let (program, args): (&str, Vec<&str>) = if cfg!(windows) {        ("cmd", vec!["/c", "claude"])    } else {        ("claude", vec![])    };    let shell = shell::Shell::detect();    let session =        pty::spawn_program(program, &args, &cwd, rows, cols, shell).map_err(|e| e.to_string())?;    install_session(&state, &app, session, "claude");    let spawned = PtySpawned {        shell: "claude".to_string(),        cwd: cwd.display().to_string(),    };    let _ = app.emit("pty://spawned", spawned.clone());    Ok(spawned)}fn validate_cwd(cwd: &str, root: &Path) -> Result<PathBuf, String> {    let cwd = PathBuf::from(cwd);    if !cwd.is_dir() {        return Err(format!("not a directory: {}", cwd.display()));    }    if !path_inside(&cwd, root) {        return Err(format!("cwd outside project root: {}", cwd.display()));    }    Ok(cwd)}/// Replace any prior session, start the emit loop (pty://* + trace://*/// + persistence), and open a session row.fn install_session(    state: &State<'_, AppState>,    app: &tauri::AppHandle,    session: pty::SessionPty,    label: &str,) {    if let Some(mut old) = state.session.lock().unwrap().take() {        let _ = old.kill();    }    *state.session.lock().unwrap() = Some(session);    let session_id = db::begin_session(&state.conn.lock().unwrap(), label).ok();    *state.session_id.lock().unwrap() = session_id;    let app2 = app.clone();    thread::spawn(move || {        let state = app2.state::<AppState>();        loop {            let mut guard = state.session.lock().unwrap();            let Some(session) = guard.as_mut() else { break };            match session.recv_output(Duration::from_millis(25)) {                Ok(pty::PtyChunk::Data(data)) => {                    let text = String::from_utf8_lossy(&data).into_owned();                    let _ = app2.emit("pty://output", PtyOutput { data: text.clone() });                    // Activity trace: parse the same stream the terminal renders.                    let steps = state.parser.lock().unwrap().feed(&text);                    for step in steps {                        let sid = *state.session_id.lock().unwrap();                        let _ = db::record_trace_step(                            &state.conn.lock().unwrap(),                            sid,                            &step.kind,                            step.file.as_deref(),                            step.command.as_deref(),                            step.detail.as_deref(),                            false,                        );                        if step.kind == "editing" {                            let mut ring = state.recent_edits.lock().unwrap();                            ring.push_back((step.file.clone().unwrap_or_default(), Instant::now()));                            while ring.len() > 64 {                                ring.pop_front();                            }                        }                        let _ = app2.emit("trace://step", step);                    }                }                Ok(pty::PtyChunk::Dropped(dropped)) => {                    let _ = app2.emit("pty://overflow", PtyOverflow { dropped });                }                Err(RecvTimeoutError::Timeout) => {                    if let Some(code) = session.poll_exit() {                        let sid = state.session_id.lock().unwrap().take();                        let _ = db::end_session(                            &state.conn.lock().unwrap(),                            sid.unwrap_or(-1),                            Some(code),                        );                        let _ = app2.emit("pty://exit", PtyExit { code: Some(code) });                        *guard = None;                        break;                    }                }                Err(RecvTimeoutError::Disconnected) => {                    let code = session.poll_exit();                    let sid = state.session_id.lock().unwrap().take();                    let _ = db::end_session(&state.conn.lock().unwrap(), sid.unwrap_or(-1), code);                    let _ = app2.emit("pty://exit", PtyExit { code });                    *guard = None;                    break;                }            }        }    });}/// Write raw bytes to the interactive session's stdin.#[tauri::command]fn pty_write(state: State<'_, AppState>, data: String) -> Result<(), String> {    let mut guard = state.session.lock().unwrap();    let session = guard        .as_mut()        .ok_or_else(|| "no active session".to_string())?;    session.write(data.as_bytes()).map_err(|e| e.to_string())}/// Resize the interactive session's PTY.#[tauri::command]fn pty_resize(state: State<'_, AppState>, rows: u16, cols: u16) -> Result<(), String> {    let mut guard = state.session.lock().unwrap();    let session = guard        .as_mut()        .ok_or_else(|| "no active session".to_string())?;    session.resize(rows, cols).map_err(|e| e.to_string())}/// Kill the interactive session. The emit loop clears it on exit.#[tauri::command]fn pty_kill(state: State<'_, AppState>) -> Result<(), String> {    let mut guard = state.session.lock().unwrap();    let session = guard        .as_mut()        .ok_or_else(|| "no active session".to_string())?;    session.kill().map_err(|e| e.to_string())}// --- watcher (M1.4 grounding + M1.5 persistence) -----------------------------/// Start watching the project folder; events stream on fs://event and/// cross-correlate with the trace (trace://confirm).#[tauri::command]fn start_watch(state: State<'_, AppState>, app: tauri::AppHandle) -> Result<(), String> {    let root = state        .project_root        .lock()        .unwrap()        .clone()        .ok_or_else(|| "project root not set".to_string())?;    let rx = watcher::watch(&root).map_err(|e| e.to_string())?;    thread::spawn(move || {        let state = app.state::<AppState>();        while let Ok(ev) = rx.recv() {            let raw = ev.path.to_string_lossy().into_owned();            // Ignore noise dirs G현 the trace should show project work.            if raw.contains("\\.git\\")                || raw.contains("/.git/")                || raw.contains("node_modules")                || raw.contains("\\target\\")                || raw.contains("/target/")            {                continue;            }            let rel = ev                .path                .strip_prefix(&root)                .map(|p| p.to_string_lossy().into_owned())                .unwrap_or(raw);            let _ = app.emit(                "fs://event",                serde_json::json!({"path": rel, "kind": ev.kind}),            );            // Grounding: did the agent recently claim to edit this file?            let confirmed = {                let mut ring = state.recent_edits.lock().unwrap();                let pos = ring                    .iter()                    .position(|(f, t)| f == &rel && t.elapsed() < Duration::from_secs(30));                if let Some(i) = pos {                    ring.remove(i);                    true                } else {                    false                }            };            if confirmed {                let _ = db::confirm_trace_steps(&state.conn.lock().unwrap(), &rel);                let _ = app.emit("trace://confirm", serde_json::json!({"path": rel}));            }        }    });    Ok(())}// --- bridge: web-AI tools + approvals (M2) -----------------------------------/// Route a tool call through the approval policy. Shared by the/// `bridge_tool` command (desktop) and the WebSocket handler (web).pub(crate) fn tool_call(    app: &tauri::AppHandle,    tool: bridge::Tool,    source: &str,) -> bridge::ToolResult {    let state = app.state::<AppState>();    let root = state.project_root.lock().unwrap().clone();    let (result, approval_id) =        state            .bridge            .lock()            .unwrap()            .submit(tool.clone(), source, root.as_deref());    let Some(id) = approval_id else {        // Auto-approved: audit immediately.        let _ = db::record_audit(            &state.conn.lock().unwrap(),            source,            "tool",            &serde_json::json!(tool).to_string(),            true,            "auto",            result.ok,        );        return result;    };    let summary = bridge::describe(&tool);    let _ = app.emit(        "bridge://approval-requested",        serde_json::json!({"id": id, "summary": summary, "source": source}),    );    if source == "web" {        // WS caller: wait for the user's decision (up to 5 minutes).        let (tx, rx) = bridge::wait_channel();        state            .bridge            .lock()            .unwrap()            .channels            .lock()            .unwrap()            .insert(id, tx);        match rx.recv_timeout(Duration::from_secs(300)) {            Ok(r) => r,            Err(_) => bridge::ToolResult::err("approval timed out"),        }    } else {        result    }}/// Desktop tool sandbox / extension relay entry (M2).#[tauri::command]fn bridge_tool(    state: State<'_, AppState>,    app: tauri::AppHandle,    tool: bridge::Tool,) -> Result<bridge::ToolResult, String> {    let _ = &state;    Ok(tool_call(&app, tool, "desktop"))}/// Resolve a pending approval: execute (allow) or deny.#[tauri::command]fn bridge_approve(    state: State<'_, AppState>,    app: tauri::AppHandle,    id: u64,    allow: bool,) -> Result<bridge::ToolResult, String> {    let root = state.project_root.lock().unwrap().clone();    let (result, req) = state        .bridge        .lock()        .unwrap()        .resolve(id, allow, root.as_deref())        .ok_or_else(|| "no such approval request".to_string())?;    let _ = db::record_audit(        &state.conn.lock().unwrap(),        &req.source,        "tool",        &serde_json::json!(req.tool).to_string(),        allow,        if allow { "user" } else { "denied" },        result.ok,    );    let _ = app.emit(        "bridge://approval-resolved",        serde_json::json!({"id": id, "allowed": allow, "result": result}),    );    Ok(result)}/// Recent audit trail (approval + auto-executed tool calls).#[tauri::command]fn bridge_audit(    state: State<'_, AppState>,    limit: Option<usize>,) -> Result<Vec<db::AuditEntry>, String> {    db::last_audit(&state.conn.lock().unwrap(), limit.unwrap_or(30)).map_err(|e| e.to_string())}// --- pairing + handoff (M2) --------------------------------------------------/// Get (or generate) the 6-digit pairing code for the extension.#[tauri::command]fn pair_get_code(state: State<'_, AppState>, app: tauri::AppHandle) -> Result<String, String> {    let mut code = state.pair_code.lock().unwrap();    if code.is_empty() {        *code = ws::new_pair_code();        let _ = db::set_setting(&state.conn.lock().unwrap(), "pair_code", &code);        let _ = app.emit("pair://code", code.clone());    }    Ok(code.clone())}/// Is an extension currently paired?#[tauri::command]fn pair_status(state: State<'_, AppState>) -> Result<bool, String> {    Ok(state.ws_connected.load(Ordering::SeqCst))}/// Set the handoff objective (editable in the handoff panel).#[tauri::command]fn set_objective(state: State<'_, AppState>, text: String) -> Result<(), String> {    *state.objective.lock().unwrap() = Some(text);    Ok(())}/// Handoff card payload, built from persisted trace state.#[derive(Clone, serde::Serialize)]pub struct Handoff {    pub objective: String,    pub progress_percent: u8,    pub files_changed: usize,    pub errors_remaining: usize,    pub next_step: Option<String>,    pub files: Vec<String>,    pub generated_at: String,}/// Build the handoff card from persisted trace state (shared by the/// desktop command and the extension's handoff-request).pub(crate) fn build_handoff_impl(state: &AppState) -> Result<Handoff, String> {    let conn = state.conn.lock().unwrap();    let stats = db::trace_stats(&conn).map_err(|e| e.to_string())?;    let mut stmt = conn        .prepare(            "SELECT DISTINCT file FROM trace_steps WHERE kind = 'editing' AND file IS NOT NULL",        )        .map_err(|e| e.to_string())?;    let files: Vec<String> = stmt        .query_map([], |r| r.get(0))        .map_err(|e| e.to_string())?        .collect::<Result<_, _>>()        .map_err(|e| e.to_string())?;    let objective = state        .objective        .lock()        .unwrap()        .clone()        .unwrap_or_else(|| "Continue the interrupted coding task".to_string());    // Honest heuristic progress: test results and error count shape it.    let progress_percent = if stats.steps == 0 {        5    } else {        let base = 30 + 10 * stats.steps.min(6) as u8;        if stats.errors > 0 {            base.saturating_sub(15)        } else if stats.steps >= 8 {            base.min(85)        } else {            base.min(70)        }    };    let generated_at = std::time::SystemTime::now()        .duration_since(std::time::UNIX_EPOCH)        .map(|d| d.as_secs().to_string())        .unwrap_or_else(|_| "0".to_string());    Ok(Handoff {        objective,        progress_percent,        files_changed: stats.files_changed,        errors_remaining: stats.errors,        next_step: stats.last_step,        files,        generated_at,    })}#[tauri::command]fn build_handoff(state: State<'_, AppState>) -> Result<Handoff, String> {    build_handoff_impl(&state)}/// Send the handoff to the paired extension (returns the payload; false/// when no extension is paired G현 the frontend falls back to copy).#[tauri::command]fn handoff_send(state: State<'_, AppState>, app: tauri::AppHandle) -> Result<Handoff, String> {    let handoff = build_handoff(state)?;    let payload = serde_json::to_value(&handoff).map_err(|e| e.to_string())?;    if !ws::push_handoff(&app, &payload) {        // still return the payload; frontend offers clipboard fallback    }    Ok(handoff)}// --- app bootstrap ------------------------------------------------------------#[cfg_attr(mobile, tauri::mobile_entry_point)]pub fn run() {    let app = tauri::Builder::default()        .plugin(tauri_plugin_opener::init())        .manage(AppState {            conn: Mutex::new(rusqlite::Connection::open_in_memory().expect("in-memory db")),            project_root: Mutex::new(None),            session: Mutex::new(None),            parser: Mutex::new(parser::Parser::new()),            pair_code: Mutex::new(String::new()),            ws_connected: AtomicBool::new(false),            ws_tx: Mutex::new(None),            bridge: Mutex::new(bridge::Bridge::new()),            session_id: Mutex::new(None),            objective: Mutex::new(None),            recent_edits: Mutex::new(VecDeque::new()),        })        .setup(|app| {            // Auto-init: app-data SQLite, persisted settings, WS server.            let dir = app.path().app_data_dir().map_err(|e| e.to_string())?;            std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;            let db_path = dir.join("bridge.db");            let conn = db::open_and_migrate(&db_path).map_err(|e| e.to_string())?;            let root = db::get_setting(&conn, "project_root").ok().flatten();            let code = match db::get_setting(&conn, "pair_code").ok().flatten() {                Some(c) if !c.is_empty() => c,                _ => {                    let c = ws::new_pair_code();                    let _ = db::set_setting(&conn, "pair_code", &c);                    c                }            };            let state = app.state::<AppState>();            *state.conn.lock().unwrap() = conn;            *state.project_root.lock().unwrap() = root.map(PathBuf::from);            *state.pair_code.lock().unwrap() = code;            ws::spawn_server(app.handle().clone());            Ok(())        })        .invoke_handler(tauri::generate_handler![            init_database,            set_project_root,            get_project_root,            git_status,            git_branch,            git_commit,            git_diff,            git_stage,            git_unstage,            git_stage_all,            git_branches,            git_checkout,            git_log,            git_commit_diff,            run_command,            start_watch,            pty_spawn,            pty_write,            pty_resize,            pty_kill,            claude_spawn,            bridge_tool,            bridge_approve,            bridge_audit,            pair_get_code,            pair_status,            set_objective,            build_handoff,            handoff_send,        ])        .build(tauri::generate_context!())        .expect("error while building tauri application");    app.run(|handle, event| {        if let tauri::RunEvent::ExitRequested { .. } = event {            // Never leave the PTY child running after the app closes.            if let Some(mut session) = handle.state::<AppState>().session.lock().unwrap().take() {                let _ = session.kill();            }        }    });}